@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : string
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + SocialSecurityNumber : string
}

class Guest {
  + Name : string
  + IsVIP : boolean
}

class Ship {
  + Name : string
  + NumberOfDecks : int
  + Length : float
  + NumberOfPassengers : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : string
  + BookingDate : date
}

class DestinationArea {
  + Name : string
  + SeaName : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise
Cruise "1" -- "*" Employee
Cruise "*" -- "*" Guest
Cruise "1" -- "*" Ship
Cruise "*" -- "1" TravelAgency
Cruise "1" -- "1" DestinationArea
Cruise "1" -- "*" Show
Cruise "1" -- "*" Ticket
Guest "1" -- "*" Ticket
Booking "1" -- "1" Cruise
Booking "1" -- "1" TravelAgency

@enduml

